corpus_block("test-facet-.R: facet_grid `axes` can draw inner axes.", {
  df <- data_frame(
      x = 1:4, y = 1:4,
      fx = c("A", "A", "B", "B"),
      fy = c("c", "d", "c", "d")
    )
  .plot("test-facet-.R: facet_grid `axes` can draw inner axes. #1", p <- ggplot(df, aes(x, y)) + geom_point())
  .plot("test-facet-.R: facet_grid `axes` can draw inner axes. #2", p + facet_grid(vars(fy), vars(fx), axes = "all"))
  case <- ggplotGrob(p + facet_grid(vars(fy), vars(fx), axes = "all"))
  .plot("test-facet-.R: facet_grid `axes` can draw inner axes. #3", p + facet_grid(vars(fy), vars(fx), axes = "margins"))
  ctrl <- ggplotGrob(p + facet_grid(vars(fy), vars(fx), axes = "margins"))
  bottom <- case$grobs[grepl("axis-b", case$layout$name)]
  bottom <- ctrl$grobs[grepl("axis-b", ctrl$layout$name)]
  left <- case$grobs[grepl("axis-l", case$layout$name)]
  left <- ctrl$grobs[grepl("axis-l", ctrl$layout$name)]
})

