corpus_block("test-facet-.R: facet labels respect both justification and margin arguments", {
  df <- data_frame(
      x = 1:2,
      y = 1:2,
      z = c("a", "aaaaaaabc"),
      g = c("b", "bbbbbbbcd")
    )
  .plot("test-facet-.R: facet labels respect both justification and margin arguments #1", base <- ggplot(df, aes(x, y)) +
      geom_point() +
      facet_grid(g ~ z) +
      theme_test())
  .plot("test-facet-.R: facet labels respect both justification and margin arguments #2", p1 <- base +
      theme(strip.text.x = element_text(hjust = 0, margin = margin(5, 5, 5, 5)),
            strip.text.y = element_text(hjust = 0, margin = margin(5, 5, 5, 5))))
  .plot("test-facet-.R: facet labels respect both justification and margin arguments #3", p2 <- base +
      theme(
        strip.text.x = element_text(
          angle = 90,
          hjust = 0,
          margin = margin(5, 5, 5, 5)
        ),
        strip.text.y = element_text(
          angle = 0,
          hjust = 0,
          margin = margin(5, 5, 5, 5)
        )
      ))
})

